import java.util.*; interface Insurance09{double insurance(double v);} abstract class Parcel09{double w;Parcel09(double w){this.w=Math.max(0,w);}abstract double ship();double total(double v){return ship();}} class Standard09 extends Parcel09{Standard09(double w){super(w);}double ship(){return 40+10*w;}} class Express09 extends Parcel09 implements Insurance09{Express09(double w){super(w);}double ship(){return 80+15*w;}public double insurance(double v){return Math.max(0,v)*.02;}double total(double v){return ship()+insurance(v);}} class Fragile09 extends Parcel09 implements Insurance09{Fragile09(double w){super(w);}double ship(){return 90+10*w;}public double insurance(double v){return Math.max(0,v)*.02;}double total(double v){return ship()+insurance(v);}} public class Week09Problem02{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double grand=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double w=s.nextDouble(),v=s.nextDouble();Parcel09 p=t.equals("EXPRESS")?new Express09(w):t.equals("FRAGILE")?new Fragile09(w):new Standard09(w);double a=p.total(v);System.out.printf("%s: %.2f%n",t,a);grand+=a;}System.out.printf("Grand total: %.2f%n",grand);}}